<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Event extends Model{protected $fillable=['title','slug','description','place','cover','starts_at','ends_at','is_published'];protected $casts=['starts_at'=>'datetime','ends_at'=>'datetime','is_published'=>'boolean'];public function scopePublished($q){return $q->where('is_published',true)->where('starts_at','>=',now()->startOfDay());}}